// 20 arranques en frío inventados, en segundos
const s = [1.6,1.7,1.7,1.8,1.8,1.9,1.9,2.0,2.0,2.1,2.1,2.2,2.2,2.3,2.4,2.6,3.1,4.8,6.2,9.5];
const orden = [...s].sort((a, b) => a - b);
const media = s.reduce((a, b) => a + b, 0) / s.length;
const pos = (p) => orden[Math.ceil(p * orden.length) - 1];
const lentos = s.filter((x) => x >= 5).length;
console.log('media', media.toFixed(2), 's | mediana', pos(0.5), 's | p90', pos(0.9), 's');
console.log('arranques de 5 s o más:', lentos, 'de', s.length, '=', (100 * lentos / s.length) + ' %');

const PASO = 1000 / 60; // 16,67 ms por cuadro
const correr = (bloqueoMs) => new Promise((res) => {
  const marcas = [];
  const iv = setInterval(() => {
    marcas.push(performance.now());
    if (marcas.length === 8) { const fin = performance.now() + bloqueoMs; while (performance.now() < fin) {} }
    if (marcas.length === 25) { clearInterval(iv); res(marcas); }
  }, PASO);
});
(async () => {
  for (const ms of [0, 50, 200]) {
    const m = await correr(ms);
    const h = m.slice(1).map((v, i) => v - m[i]);
    const perdidos = h.reduce((s, x) => s + Math.max(0, Math.floor(x / PASO) - 1), 0);
    console.log(`tarea que bloquea ${ms} ms -> pausa más larga ${Math.max(...h).toFixed(0)} ms, cuadros perdidos: ${perdidos}`);
  }
})();
